import React, { useEffect, useState } from 'react';
import { getOrders } from '../data/dataFetching';


function Orders() {

    const [orders, setOrders] = useState([]);

    useEffect(() => {
        getOrders().then(data => setOrders(data));
    }, []);

    let [search, setSearch] = useState("")
    let [sort, setSort] = useState("name")

    function onSearchChange(e) {
        setSearch(e.target.value)
    }

    function onSortChange(e) {
        setSort(e.target.value)
    }

    function getSortedOrdersData() {
        return orders
            .filter((item) => {
                return item.id.toString().includes(search) ||
                    item.date.toString().includes(search) ||
                    item.customerName.toLowerCase().includes(search.toLowerCase()) ||
                    item.status.toLowerCase().includes(search.toLowerCase()) ||
                    item.payment.toLowerCase().includes(search.toLowerCase())
            })
            .sort((a, b) => {
                return (a[sort] + "").localeCompare(b[sort] + "")
            })
    }


    return (
        <>

            <h1>Orders</h1>

            <div className="tableFunctions">

                <div className="tableSeachbar">
                    <i class="bi bi-search"></i>
                    <input class="tableSeachInput" type="text" placeholder="Search" onChange={onSearchChange} value={search}></input>
                </div>

                <select className="tableSort" onChange={onSortChange} value={sort}>
                    <option selected value="id">
                        Order ID
                        <i className='bi bi-chevron-down'></i>
                    </option>
                    <option value="date">Date</option>
                    <option value="customerName">Customer</option>
                    <option value="status">Status</option>
                    <option value="payment">Payment</option>
                </select>

            </div>

            <div className="table-container">
                <table>
                    <thead>
                        <tr>
                            <th>Order ID</th>
                            <th>Date</th>
                            <th>Customer</th>
                            <th>Satatus</th>
                            <th>Payment</th>
                        </tr>
                    </thead>

                    <tbody>
                        {orders.length > 0 &&
                            getSortedOrdersData().map((item) => {
                                return <tr>

                                    <td><a href={"/orders/order-details/" + item.id}>{item.id}</a></td>
                                    <td>{item.date}</td>
                                    <td>{item.customerName}</td>
                                    <td>{item.status}</td>
                                    <td>{item.payment}</td>
                                </tr>
                            })
                        }
                    </tbody>
                </table>

            </div>


        </>
    )
}

export default Orders;
